INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(21101, 'Hosea 9:8', 'Hosea', 9, 8, '&nbsp;پېغمبر د خُدائ پاک د طرف نه د بنى اِسرائيل محافظ دے. خو چې چرته هم هغه ځى نو هلته د هغۀ د راګېرولو دپاره دام خور وى، بلکې د خُدائ پاک په کور کښې هم د هغۀ نه نفرت کيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21102, 'Hosea 9:9', 'Hosea', 9, 9, '&nbsp;هغوئ په خپله بدعملۍ کښې دومره ککړ شوى دى لکه چې هغوئ ډېره موده مخکښې په جبعه کښې په بدعملۍ کښې ککړ شوى وُو. خُدائ پاک ته به د هغوئ ګناهونه ياد وى او سزا به ورته ورکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21103, 'Hosea 9:10', 'Hosea', 9, 10, '&nbsp;مالِک خُدائ فرمائى، ”کله چې ما اول ځل بنى اِسرائيل وليدل، نو دا داسې وُو لکه چې په صحرا کښې انګور ومومى. ما ستاسو پلار نيکۀ داسې وليدل لکه چې د موسم وړومبى پاخۀ شوى اينځر مې ليدلى وى. خو کله چې هغوئ د فعور غرۀ ته راغلل، نو هلته هغوئ خپل ځانونه شرمناک بعل بُت ته وقف کړل. نو داسې چې هغوئ څۀ سره مينه وکړه نو د هغې په شان پليت شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21104, 'Hosea 9:11', 'Hosea', 9, 11, '&nbsp;د بنى اِسرائيل شان او شوکت به د مارغۀ په شان والوځى او د هغوئ به نور بچى نۀ پېدا کيږى او نۀ به يې ښځې اُميدواره کيږى او نۀ به يې اولاد په خېټه کيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21105, 'Hosea 9:12', 'Hosea', 9, 12, '&nbsp;خو کۀ د هغوئ بچى پېدا هم شى، نو زۀ به يې ترې نه واخلم او يو به هم ژوندے پرې نۀ ږدم. په هغوئ افسوس، ځکه چې هغوئ به زۀ پرېږدم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21106, 'Hosea 9:13', 'Hosea', 9, 13, '&nbsp;ما وکتل چې بنى اِسرائيل د صور په شان ښائسته شول. خو اوس به بنى اِسرائيل خپل اولاد حلالولو دپاره رابهر کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21107, 'Hosea 9:14', 'Hosea', 9, 14, '&nbsp;اے مالِکه خُدايه، زۀ ستا نه د دې خلقو دپاره څۀ سوال وکړم؟ د هغوئ ښځې شنډې کړه. او د هغوئ په سينو کښې پئ اوچ کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21108, 'Hosea 9:15', 'Hosea', 9, 15, '&nbsp;مالِک خُدائ فرمائى، ”د هغوئ ټول بد عملونه په جِلجال کښې شروع شول. نو هلته مې د هغوئ نه نفرت شروع کړو او د هغوئ د بدعملۍ په وجه به زۀ هغوئ د خپل مُلک نه وشړم. زۀ به د هغوئ سره نوره مينه نۀ کوم، د هغوئ ټول آفسران سرکشه دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21109, 'Hosea 9:16', 'Hosea', 9, 16, '&nbsp;بنى اِسرائيل وهلے شوى دى، د هغوئ جرړې اوچې شوې دى او هيڅ مېوه به نۀ نيسى. خو کۀ د هغوئ بچى پېدا هم شى، نو زۀ به د هغوئ ګران اولاد ووژنم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21110, 'Hosea 9:17', 'Hosea', 9, 17, '&nbsp;زما خُدائ پاک به هغوئ رد کړى، ځکه چې هغوئ ورته غوږ نۀ نيولو او هغوئ به په قومونو کښې در په در ګرځى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21111, 'Hosea 10:1', 'Hosea', 10, 1, '&nbsp;بنى اِسرائيل د انګورو زرخيزه بوټے وو چې ښۀ کافى مېوه به يې نيوله. خو څومره چې يې مېوه زياتېده نو دومره ډېرې به يې د بُتانو قربان‌ګاه جوړولې. څومره چې د هغوئ مُلک ترقى کوله نو دومره يې د بُتانو مخصوص ستنې ښائسته کولې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21112, 'Hosea 10:2', 'Hosea', 10, 2, '&nbsp;د چا زړونه چې د دوکې نه ډک دى نو هغوئ ته خو به د خپلو ګناهونو سزا ملاويږى. خُدائ پاک به د هغوئ قربان‌ګاه ورانې کړى او د هغوئ مقدسې ستنې به ټوټې ټوټې کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21113, 'Hosea 10:3', 'Hosea', 10, 3, '&nbsp;نو خلق به ډېر زر دا خبره وکړى چې، ”زمونږ بادشاه ځکه نشته چې مونږ د مالِک خُدائ نه نۀ يرېدو. خو کۀ بادشاه وے هم، نو هغۀ زمونږ دپاره څۀ کولے شول؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21114, 'Hosea 10:4', 'Hosea', 10, 4, '&nbsp;هغوئ لافې کوى، د دروغو قسمونه خورى او تشې وعدې کوى. د هغوئ اِنصاف د هغه زهرژن بوټو په شان دے چې د تخم دپاره تيار پټى کښې پخپله رازرغون شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21115, 'Hosea 10:5', 'Hosea', 10, 5, '&nbsp;د سامريه ښار اوسېدونکى د يرې نه ريږدى چې په بيت‌آون کښې به د سخى بُت سره څۀ کيږى. د دې خلق به د دې دپاره ژړا کوى، او د دې اِمامان به د دې شان او شوکت يادوى او ماتم به کوى، ځکه چې دا به د دوئ نه بل مُلک ته يوړلے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21116, 'Hosea 10:6', 'Hosea', 10, 6, '&nbsp;هغه بُت به اسور ته يوړلے شى چې عظيم بادشاه ته په محصُول کښې پېش کړے شى. بنى اِسرائيل به بې‌عزته شى او وبه شرميږى ځکه چې هغوئ په دې بُت باندې يقين کولو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21117, 'Hosea 10:7', 'Hosea', 10, 7, '&nbsp;سامريه او د هغې بادشاه به داسې يوړلے شى لکه چې د اوبو دپاسه د لرګى يوه ټوکړه وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21118, 'Hosea 10:8', 'Hosea', 10, 8, '&nbsp;د آون علاقائى عبادتخانې به تباه شى چرته چې بنى اِسرائيلو ګناه کوله. د هغوئ په قربان‌ګاهو باندې به واښۀ او ازغى راشنۀ شى. نو خلق به غرونو ته چغې وهى چې، ”مونږ پټ کړه.“ او غونډو ته به چغې وهى چې، ”په مونږ راپرېوځه.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21119, 'Hosea 10:9', 'Hosea', 10, 9, '&nbsp;مالِک خُدائ فرمائى، ”اے بنى اِسرائيله، د هغه وخت نه چې تا په جبعه کښې ګناه کوله تر اوسه پورې هم هغه شان ګناه کوې. نو ولې دا مناسبه نۀ وه چې په دغه بدعملو په جبعه کښې جنګ راغلو؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21120, 'Hosea 10:10', 'Hosea', 10, 10, '&nbsp;نو اوس چې کله زما مرضى وى زۀ به تاسو له سزا درکړم. قومونه به ستاسو خِلاف راجمع شى کله چې تاسو ته ستاسو د ګناهونو سزا دوه چنده مِلاو شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21121, 'Hosea 10:11', 'Hosea', 10, 11, '&nbsp;اِسرائيل يو تربيت يافته سخے دے او ښۀ په شوق غنم غوبل کوى. خو بيا ما په خپله د دې په ښائسته څټ د سخت محنت دپاره جغ کېښودو. ما يهوداه يوې کولو ته جوړ کړے دے او اِسرائيل به دا په خپله ماله کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21122, 'Hosea 10:12', 'Hosea', 10, 12, '&nbsp;ما ورته ووئيل چې، د صداقت ښۀ تخم وکَره نو د مينې فصل به وريبې. د خپلو زړونو سخته زمکه يوه وکړئ ځکه چې اوس د مالِک خُدائ د لټون وخت دے چې هغه راشى او په تاسو د صداقت باران وورَوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21123, 'Hosea 10:13', 'Hosea', 10, 13, '&nbsp;خو تا بدعملى وکَرله او د بې‌اِنصافۍ فصل دې ورېبلو. تا د دوکې مېوه خوړلې ده. ځکه چې تا په خپلو جنګى ګاډو او په خپلو بې‌شمېره فوجيانو اعتبار کولو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21124, 'Hosea 10:14', 'Hosea', 10, 14, '&nbsp;نو ځکه به ستا په خلقو جنګ راشى او ستاسو ټولې قلعې به تباه شى. دا به هم هغه شان وى لکه څنګه چې شلمن بادشاه بيت‌اربيل په جنګ کښې تباه کړو او ميندې يې سره د هغوئ د بچو زمکې له راوويشتلې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21125, 'Hosea 10:15', 'Hosea', 10, 15, '&nbsp;نو اے د بيت‌ايل خلقو، تاسو سره به هم داسې کار کيږى، ځکه چې ستاسو بدعملى د حد نه زياته ده. څنګه چې د عدالت ورځ شروع شى، نو د اِسرائيل بادشاه به تباه او برباد شى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21126, 'Hosea 11:1', 'Hosea', 11, 1, '&nbsp;مالِک خُدائ فرمائى، ”کله چې بنى اِسرائيل د وړوکى ماشوم په شان وو، نو مينه مې ورسره کوله، او ما خپل زوئ د مِصر نه راوبللو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21127, 'Hosea 11:2', 'Hosea', 11, 2, '&nbsp;خو چې څومره ما ورته آوازونه کول، نو هغه هومره زما نه لرې کېدو. زما خلقو د بعل بُتانو ته قربانۍ پېش کړې، او بُتانو ته يې خوشبويۍ سوزولې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21128, 'Hosea 11:3', 'Hosea', 11, 3, '&nbsp;ما پخپله بنى اِسرائيل ته د ګرځېدو چل وښودلو، ما د هغۀ لاس نيولے وو او د هغۀ رهنمائى مې کوله، خو هغۀ ته پته نۀ لګېده او نۀ يې پرواه ساتله چې هغه زۀ وم چې د هغۀ خيال مې ساتلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21129, 'Hosea 11:4', 'Hosea', 11, 4, '&nbsp;ما بنى اِسرائيل د خپلې مينې او رحم رسۍ سره ځان ته رانزدې کړو. ما د هغۀ د څټ نه جغ اوچت کړو، او زۀ په خپله ورټيټ شوم او خوراک مې ورکړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21130, 'Hosea 11:5', 'Hosea', 11, 5, '&nbsp;خو هغوئ به مِصر ته واپس شى او د اسور بادشاه به په هغوئ حکومت کوى، ځکه چې هغوئ ما ته د راګرځېدو نه اِنکار کړے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21131, 'Hosea 11:6', 'Hosea', 11, 6, '&nbsp;د هغوئ په ښارونو کښې به جنګ کوى او د ښار دروازې به يې ماتې کړى. هغوئ به د خپلو غلطو منصوبو له وجې تباه کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21132, 'Hosea 11:7', 'Hosea', 11, 7, '&nbsp;زما خلقو کلکه فېصله کړې ده چې ما پرېږدى. هغوئ په خولۀ خو ما ته حق تعالىٰ وائى خو زۀ به هغوئ بچ نۀ کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21133, 'Hosea 11:8', 'Hosea', 11, 8, '&nbsp;اے بنى اِسرائيله، زۀ تا څنګه پرېښودے شم؟ زۀ تا څنګه دشمن ته حواله کولے شم؟ زۀ تا څنګه لکه د ادمه نورو ته حواله کولے شم؟ يا دې د ضبوئيم په شان څنګه تباه کولے شم؟ زما اراده سراسر بدله شوه. ځکه چې زما بې‌مثاله مينه ستا دپاره راوچته شوه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21134, 'Hosea 11:9', 'Hosea', 11, 9, '&nbsp;زۀ به تا له په غصه کښې سزا نۀ درکوم، زۀ به بنى اِسرائيل بيا نۀ تباه کوم. ځکه چې زۀ بنى آدم نۀ يم بلکې خُدائ پاک يم. زۀ مقدس ذات يم او ستاسو په مينځ کښې استوګنه کوم. زۀ به بيا په غضب کښې نۀ راځم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21135, 'Hosea 11:10', 'Hosea', 11, 10, '&nbsp;کله چې زۀ د خپلو خلقو په دشمنانو د ازمرى په شان وغورېږم نو زما خلق به په ما پسې راروان شى. هغوئ به د نمرپرېواتۀ طرف نه په منډه منډه راشى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21136, 'Hosea 11:11', 'Hosea', 11, 11, '&nbsp;هغوئ به په يرې او ريږدېدو سره د مارغانو په شان د مِصر نه راشى او د اسور نه به د ګوګوشتکو په شان واپس راشى. زۀ به هغوئ خپلو کورونو ته واپس راولم. ما، مالِک خُدائ دا فرمائيلى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21137, 'Hosea 11:12', 'Hosea', 11, 12, '&nbsp;اِسرائيل زۀ په دروغو سره رانيولے يم، او دوکې سره يې زما محاصره کړې ده. خو يهوداه تر اوسه پورې د خُدائ پاک فرمانبردار دے، او مقدس ذات سره وفادار دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21138, 'Hosea 12:1', 'Hosea', 12, 1, '&nbsp;بنى اِسرائيل چې ټوله ورځ هر کار هم کوى نو هغه بې‌فائدې وى. دوکه او ظلم زياتے په هغوئ کښې زياتيږى. د اسور سره د معاهدې باوجود خو بيا هم مِصر ته د زيتُونو تېل لېږى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21139, 'Hosea 12:2', 'Hosea', 12, 2, '&nbsp;مالِک خُدائ به په عدالت کښې يهوداه سره هم جنګيږى. هغه به بنى اِسرائيل له د هغۀ د عمل په مطابق سزا ورکوى او هغۀ ته به د خپل عمل بدله ملاويږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21140, 'Hosea 12:3', 'Hosea', 12, 3, '&nbsp;يعقوب هم د مور په خېټه کښې خپل ورور د پوندې نه ونيوو او کله چې بالغ شو، نو هغۀ خُدائ پاک سره جګړه وکړه،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21141, 'Hosea 12:4', 'Hosea', 12, 4, '&nbsp;هغۀ د يوې فرښتې خِلاف جنګ وکړو او جنګ يې وګټلو. هغۀ وژړل او د برکت سوال يې وکړو. په بيت‌ايل کښې خُدائ پاک هغۀ ته څرګند شو او کلام يې ورسره وکړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21142, 'Hosea 12:5', 'Hosea', 12, 5, '&nbsp;مالِک خُدائ ربُ الافواج، مالِک خُدائ د هغۀ نوم دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21143, 'Hosea 12:6', 'Hosea', 12, 6, '&nbsp;نو اوس خپل خُدائ پاک ته راوګرځئ. د هغۀ مينه او اِنصاف قائم ساتئ او همېشه د هغۀ نه په اُميد کښې اوسئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21144, 'Hosea 12:7', 'Hosea', 12, 7, '&nbsp;بنى اِسرائيل هغه تاجران دى چې په لاس کښې يې د بې‌ايمانۍ تله وى او د دوکې کولو سره مينه کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21145, 'Hosea 12:8', 'Hosea', 12, 8, '&nbsp;بنى اِسرائيل وائى، ”زۀ ډېر مالداره يم، زۀ دولتمند شوے يم. هيڅوک به دا ثابته نۀ کړى چې په دې ټول مال حال حاصلولو کښې زما نه څۀ قصور يا ګناه شوې ده.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21146, 'Hosea 12:9', 'Hosea', 12, 9, '&nbsp;خو زۀ، مالِک خُدائ ستاسو هغه خُدائ پاک يم چې چا د مِصر نه راوويستلئ، زۀ به يو ځل بيا تاسو د پخوا په شان په خېمو کښې اوسوم لکه چې هر کال د جونګړو په اختر کښې اوسېږئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21147, 'Hosea 12:10', 'Hosea', 12, 10, '&nbsp;ما د پېغمبرانو سره کلام وکړو او ما پخپله ډيرې روياګانې څرګندې کړې او د پېغمبرانو په ذريعه مې درته تعبير کړې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21148, 'Hosea 12:11', 'Hosea', 12, 11, '&nbsp;خو په جِلعاد کښې د بُتانو عبادت کيږى او څوک چې د هغوئ عبادت کوى هغوئ د هيڅ کار نۀ دى. او په جِلجال کښې هم هغوئ غوَيان قربانى کوى خو د هغوئ د قربانو د ځايونو نه د کاڼو ډيرى جوړ شوى دى لکه څنګه چې د يوه شوى پټى په غاړه کښې د کاڼو ډيرى پراتۀ وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21149, 'Hosea 12:12', 'Hosea', 12, 12, '&nbsp;يعقوب آرام وطن ته وتښتېدو، هلته هغۀ د ښځې حاصلولو دپاره خِدمت وکړو، د هغې په عوض کښې هغۀ ګډې څرولې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21150, 'Hosea 12:13', 'Hosea', 12, 13, '&nbsp;خو بيا مالِک خُدائ د يو پېغمبر په وسيله بنى اِسرائيل د مِصر نه رابهر کړل او د يو پېغمبر په ذريعه يې د هغۀ خيال وساتلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21151, 'Hosea 12:14', 'Hosea', 12, 14, '&nbsp;خو بنى اِسرائيل مالِک خُدائ سخت غصه کړے دے، هغۀ چې کومه وينه تويه کړې ده اوس به ورسره د هغې حساب کيږى، هغۀ چې د مالِک خُدائ توهين کړے دے د هغې مناسبه سزا به ورکوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21152, 'Hosea 13:1', 'Hosea', 13, 1, '&nbsp;ستاسو مشرانو به چې کله هم خبرې کولې نو ټول اِسرائيليان به ريږدېدل، کۀ څۀ هم چې دوئ اهم خلق وُو بلکې بعل ته په عبادت کولو سره يې ګناه وکړه او په دې کولو سره هغوئ خپله تباهى يقينى کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21153, 'Hosea 13:2', 'Hosea', 13, 2, '&nbsp;اوس هغوئ ګناه کولو کښې اضافه کوى او خپلو ځانونو دپاره د سپينو زرو نه بُتان جوړوى. بيا چې انسان د خپلو لاسونو مهارت سره کوم بُتان جوړ کړى وُو نو هم هغه بُتانو ته وائى چې، ”دې ته قربانۍ پېش کړئ. او دا د سخى بُت ښکل کړئ.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21154, 'Hosea 13:3', 'Hosea', 13, 3, '&nbsp;نو ځکه دا خلق به د سحر د دُهند په شان عارضى وى او د سحر په نمر کښې د زر ختمېدونکې پرخې په شان وى. هغوئ به د هغه بوسو په شان وى چې هوا يې د درمند نه وړى، هغوئ به د انګيټۍ د لوږى په شان وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21155, 'Hosea 13:4', 'Hosea', 13, 4, '&nbsp;خو زۀ مالِک خُدائ ستاسو خُدائ پاک يم، چا چې تاسو د مِصر نه راوويستلئ. زما نه بغېر بل خُدائ مۀ منئ ځکه چې زما نه بغېر بل خلاصونکے نشته.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21156, 'Hosea 13:5', 'Hosea', 13, 5, '&nbsp;ما په صحرا کښې ستاسو خيال ساتلے دے په هغه اوچ بيابان کښې چرته چې هيڅ اوبۀ نۀ وې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21157, 'Hosea 13:6', 'Hosea', 13, 6, '&nbsp;خو کله چې تاسو په خېټه ښۀ ماړۀ شوئ نو تاسو مغروره شوئ او زۀ مو هېر کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21158, 'Hosea 13:7', 'Hosea', 13, 7, '&nbsp;نو زۀ به اوس په تاسو باندې لکه د ازمرى په شان حمله وکړم. د پړانګ په شان به زۀ تاسو ته په لار کښې پټ ناست يم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21159, 'Hosea 13:8', 'Hosea', 13, 8, '&nbsp;زۀ به په تاسو باندې لکه د هغه مېلو په شان حمله وکړم چې بچى ترېنه پټ کړے شوى وى او ستاسو سينه به وشلوم. لکه د ازمرى به مو لواړ تېر کړم او لکه د يو ځنګلى ځناور به مو ټوټې ټوټې کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21160, 'Hosea 13:9', 'Hosea', 13, 9, '&nbsp;اے بنى اِسرائيله، زۀ تاسو تباه کوم، ځکه چې تاسو زما خلاف يئ، نو څوک به ستاسو مدد کوى؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21161, 'Hosea 13:10', 'Hosea', 13, 10, '&nbsp;اوس ستا بادشاه چرته دے چې هغه ستا ټولو ښارونو ته راشى او تا بچ کړى؟ او ستا هغه مشران چرته دى چې تا به غوښتل، او وئيل به دې چې ما له بادشاه او آفسران راکړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21162, 'Hosea 13:11', 'Hosea', 13, 11, '&nbsp;ما په خپله غصه کښې تاسو له بادشاهان درکړى دى او په قهر کښې مې درنه اخستى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21163, 'Hosea 13:12', 'Hosea', 13, 12, '&nbsp;د بنى اِسرائيلو ګناهونه او جرمونه ليکلے شوى دى او د حساب دپاره دا محفوظ پراتۀ دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21164, 'Hosea 13:13', 'Hosea', 13, 13, '&nbsp;د ماشوم د پېدا کېدو درد شروع شوے دے خو هغه ماشوم ناپوهه دے، او نۀ غواړى چې د مور د خېټې نه راوځى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21165, 'Hosea 13:14', 'Hosea', 13, 14, '&nbsp;زۀ ولې فديه ورکړم او هغوئ د عالِم ارواح نه آزاد کړم؟ زۀ هغوئ د مرګ د پنجې نه ولې خلاص کړم؟ اے مرګه، ستا د طاقت هغه لشه څۀ شوه؟ اے عالمِ ارواح ستا بربادى څۀ شوه؟ هغې نه کار واخله ځکه چې زۀ به رحم نۀ کوم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21166, 'Hosea 13:15', 'Hosea', 13, 15, '&nbsp;کۀ څۀ هم بنى اِسرائيل د لوخو د پاڼو په شان راشنۀ کيږى، نو زۀ به نمرخاتۀ طرف نه يوه ګرمه هوا راولېږم او هغه هوا به د هغوئ کوهى او چينې اوچې کړى. دا به د ځان سره ټول قيمتى څيزونه يوسى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21167, 'Hosea 13:16', 'Hosea', 13, 16, '&nbsp;سامريه به د خپل قصور سزا برداشت کوى، ځکه چې هغې زما خِلاف سرکشۍ کړې ده. د سامريه خلق به په جنګ کښې مړۀ شى، د هغوئ ماشومان به په زمکه راوغورزولے شى او د هغوئ د اُميدوارو ښځو خېټې به وڅيرلے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21168, 'Hosea 14:1', 'Hosea', 14, 1, '&nbsp;اے بنى اِسرائيله، مالِک خُدائ خپل خُدائ پاک ته راوګرځه، ولې چې ستا ګناهونه ستا د راغورزېدو سبب جوړ شوى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21169, 'Hosea 14:2', 'Hosea', 14, 2, '&nbsp;مالِک خُدائ ته راوګرځئ او د خپلو ګناهونو اقرار وکړئ، او هغۀ ته ووايئ، ”زمونږ ټول ګناهونه معاف کړه او رحم وکړه او مونږ قبول کړه چې مونږ ستا ثناء صِفت سره تا ته قربانى پېش کړُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21170, 'Hosea 14:3', 'Hosea', 14, 3, '&nbsp;اسور مونږ نۀ شى بچ کولے او نۀ مو جنګى آسونه حِفاظت کولے شى. مونږ چې کوم بُتان جوړ کړى دى هغې ته به هيڅکله نۀ وايو چې تاسو زمونږ معبودان يئ. ځکه چې صرف هم تۀ، مالِک خُدائ په يتيم باندې رحم کوې.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21171, 'Hosea 14:4', 'Hosea', 14, 4, '&nbsp;بيا مالِک خُدائ فرمائى، ”زۀ به د هغوئ بې‌وفائى ختمه کړم او شفا به ورکړم. زۀ به د زړۀ د اخلاصه د هغوئ سره مينه کوم، زۀ هغوئ ته نور غصه نۀ يم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21172, 'Hosea 14:5', 'Hosea', 14, 5, '&nbsp;زۀ به د بنى اِسرائيل دپاره د پرخې په شان يم. زۀ به هغوئ لکه د نيلوفر ګل و ګلزار کړم، د لبنان د دِيار د ونو په شان به يې جرړې مضبوطې وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21173, 'Hosea 14:6', 'Hosea', 14, 6, '&nbsp;د هغې څانګې به خورې شى لکه د زيتون د ښائسته ونو په شان. د هغې خوشبو به د لبنان د دِيار د ونو په شان وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21174, 'Hosea 14:7', 'Hosea', 14, 7, '&nbsp;زما خلق به يو ځل بيا زما د سورې لاندې اوسيږى. هغوئ به لکه د غلې په شان لوئ شى، او د انګورو د بوټى په شان به ګلونه نيسى. د هغوئ مشهورتيا به د لبنان د ميو په شان وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21175, 'Hosea 14:8', 'Hosea', 14, 8, '&nbsp;اے بنى اِسرائيله، د بُتانو نه ځان لرې ساته. هغه زۀ يم چې ستاسو د دُعاګانو جواب درکوم او ستاسو خيال ساتم. زۀ د هغه ونې په شان يم چې همېشه شنه وى، ستاسو ټولې مېوې زما د طرف نه دى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21176, 'Hosea 14:9', 'Hosea', 14, 9, '&nbsp;هر څوک چې هوښيار وى نو هغه دې په دې خبرو باندې پوهه شى او په خپلو زړونو کښې دې ځائ ورکړى. د مالِک خُدائ لارې صحيح دى او صادقان خلق په دې روان وى، خو سرکشه به په دې لارو تيندک وخورى او وبه غورزيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21177, 'Joel 1:1', 'Joel', 1, 1, '&nbsp;د مالِک خُدائ کلام چې په يوايل د فتوايل په زوئ نازل شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21178, 'Joel 1:2', 'Joel', 1, 2, '&nbsp;اے مشرانو، دا واورئ. تاسو ټول غوږ شئ، څوک چې په دې مُلک کښې اوسېږئ. ولې ستاسو په ژوند کښې يا ستاسو د پلار نيکۀ په ژوند کښې داسې څۀ کله پېښ شوى دى؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21179, 'Joel 1:3', 'Joel', 1, 3, '&nbsp;دا خپل اولاد ته ووايئ، او هغوئ دې دا خپل اولاد ته ووائى او داسې دې دا ياد تر نسلونو پورې تازه وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21180, 'Joel 1:4', 'Joel', 1, 4, '&nbsp;د قحطۍ د مُلخانو د لښکرو نه چې څۀ پاتې شُو، هغه غټو مُلخانو وخوړل، چې د غټو مُلخانو نه څۀ پاتې شُو نو هغه وړو مُلخانو وخوړل، او څۀ چې د وړو مُلخانو نه پاتې شُو، نو هغه نورو مُلخانو وخوړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21181, 'Joel 1:5', 'Joel', 1, 5, '&nbsp;اے شرابيانو، ويښ شئ او وژاړئ، اے مے څښونکو، تاسو ټول افسوس وکړئ، د نوؤ ميو په وجه افسوس وکړئ، ځکه چې دا ستاسو د شونډو نه راښکلے شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21182, 'Joel 1:6', 'Joel', 1, 6, '&nbsp;د هغوئ ټول لښکر زما په مُلک حمله وکړه، چې طاقتور او د شمېر نه بهر دى، د هغوئ غاښونه د زمرى په شان تېرۀ دى او د هغوئ داړې د زمرۍ په شان دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21183, 'Joel 1:7', 'Joel', 1, 7, '&nbsp;هغوئ زما د انګورو بوټى تباه کړى دى او زما د اينځرو ونې يې تباه کړې دى، پوستکى يې ترې نه ويستى دى او تباه کړى يې دى، د دې څانګې يې خالى او لغړى پرېښودې دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21184, 'Joel 1:8', 'Joel', 1, 8, '&nbsp;لکه د هغه پېغلې وژاړئ چا چې د ماتم جامې اغوستې وى او د خپل چنغول په مرګ ژړا انګولا کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21185, 'Joel 1:9', 'Joel', 1, 9, '&nbsp;د غلې او د څښلو نذرانې د مالِک خُدائ په کور کښې ختمې شوې. هغه اِمامان ژاړى څوک چې د مالِک خُدائ په وړاندې خِدمت کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21186, 'Joel 1:10', 'Joel', 1, 10, '&nbsp;پټى تباه شوى دى، زمکه اوچه شوه، غله تباه شوه، انګور ضائع شُو، او د زيتُونو تېل ختم شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21187, 'Joel 1:11', 'Joel', 1, 11, '&nbsp;اے زميدارانو غمژن اوسئ، اے د انګورو د باغ ماليانو، ژړا کوئ، د غنم او د اوربشو دپاره غمژن شئ، ځکه چې د فصل پټى تباه شوى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21188, 'Joel 1:12', 'Joel', 1, 12, '&nbsp;د انګورو بوټى اوچ شُو او د اينځرو ونې وچې شوې، د انارو ونې، د کجورو ونې، او د سيوانو ونې او ټولې مېوه دارې ونې وچې شوې دى. او يقيناً د خلقو خوشحالى ورسره ورکه شوې ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21189, 'Joel 1:13', 'Joel', 1, 13, '&nbsp;اے اِمامانو د ټاټ جامې واچوئ او وژاړئ، او ماتم وکړئ تاسو څوک چې په قربان‌ګاه کښې خِدمت کوئ. راشئ، ټوله شپه د ټاټ په جامو کښې تېره کړئ، تاسو څوک چې د مالِک خُدائ په حضور کښې خِدمت کوئ. ځکه چې ستاسو د خُدائ کور د غلې او د څښلو د نذرانو نه محروم شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21190, 'Joel 1:14', 'Joel', 1, 14, '&nbsp;د مقدسې روژې نيولو اعلان وکړئ، او د خلقو مقدسه اجتماع راوغواړئ. مشران او د مُلک ټول خلق د مالِک خُدائ د خپل خُدائ پاک کور ته راوغواړئ او مالِک خُدائ ته وژاړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21191, 'Joel 1:15', 'Joel', 1, 15, '&nbsp;افسوس په هغه ورځ، ځکه چې د مالِک خُدائ هغه د قيامت ورځ رانزدې ده، په کومه به چې قادر خُدائ تباهى راولى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21192, 'Joel 1:16', 'Joel', 1, 16, '&nbsp;زمونږ خوراک زمونږ د سترګو په وړاندې غېب شو، او خندا خوشحالى زمونږ د خُدائ پاک په کور کښې بنده شوه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21193, 'Joel 1:17', 'Joel', 1, 17, '&nbsp;تخم د زمکې لاندې اوچ شو. د غلې ګودامونه خالى او وران ويجاړ پراتۀ دى، خمبې تشې او ماتې شوې ځکه چې تخم اوچ شوے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21194, 'Joel 1:18', 'Joel', 1, 18, '&nbsp;څاروى د لوږې نه چغې وهى، د څاروو رمې اخوا ديخوا پرېشانه ګرځى ځکه چې د هغوئ دپاره شينکے نشته، تر دې چې د ګډو رمې هم په تکليف کښې دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21195, 'Joel 1:19', 'Joel', 1, 19, '&nbsp;اے مالِکه خُدايه، زۀ تا ته د مدد دپاره فرياد کوم، ځکه چې اور د څرېدو ځايونه وسوزول او لمبو د ټولو پټو ونې وسوزولې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21196, 'Joel 1:20', 'Joel', 1, 20, '&nbsp;تر دې چې ځنګلى ځناور هم تا ته فرياد کوى ځکه چې د اوبو نِهرونه اوچ شوى دى، او د اور لمبو په صحرا کښې څرن ځايونه سوزولى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21197, 'Joel 2:1', 'Joel', 2, 1, '&nbsp;په صيون کښې بيګل وغږوئ، او زما په مقدس غرۀ د جنګ اعلان وکړئ. او د دې مُلک اوسېدونکى دې ټول د يرې نه ولړزيږى، ځکه چې د مالِک خُدائ د قيامت ورځ راتلونکى ده، بلکې نزدې ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21198, 'Joel 2:2', 'Joel', 2, 2, '&nbsp;دا د تورې تيارې او غم ورځ ده، د ګڼو وريځو او تورو تيارو يوه ورځ ده. لکه څنګه چې د سحر رڼا په غرونو راخوريږى داسې يو لوئ او طاقتور لښکر راروان دے، چې داسې به نۀ پخوا چا ليدلے وى او نۀ به په راتلونکى وخت کښې کله راشى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21199, 'Joel 2:3', 'Joel', 2, 3, '&nbsp;د هغوئ نه وړاندې اور هر څۀ سوزوى، او د هغوئ شاته د اور لمبې روانې وى. د هغوئ په وړاندې مُلک لکه د باغِ عدن په شان ښکلے پروت دے. خو د هغوئ نه وروستو زمکه لکه د صحرا په شان شى او د هغوئ نه هيڅ شے بچ نۀ پاتې کيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21200, 'Joel 2:4', 'Joel', 2, 4, '&nbsp;هغوئ په ليدلو کښې د آسونو په شان ښکارى، او هغوئ د جنګى آسونو په شان منډې وهى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');